-- Recovery v2 continuation metadata; excluded from the business snapshot.
CREATE TABLE app_recovery_watermark(id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL CHECK(revision BETWEEN 0 AND 9007199254740991)) STRICT;
INSERT INTO app_recovery_watermark VALUES(1,0);
CREATE TRIGGER recovery_watermark_no_reinsert BEFORE INSERT ON app_recovery_watermark WHEN EXISTS(SELECT 1 FROM app_recovery_watermark WHERE id=1) BEGIN SELECT RAISE(ABORT,'Retain recovery watermark'); END;
CREATE TRIGGER recovery_watermark_monotonic BEFORE UPDATE ON app_recovery_watermark WHEN NEW.id<>OLD.id OR NEW.revision<>OLD.revision+1 BEGIN SELECT RAISE(ABORT,'Recovery watermark must advance exactly once'); END;
CREATE TRIGGER recovery_watermark_no_delete BEFORE DELETE ON app_recovery_watermark BEGIN SELECT RAISE(ABORT,'Retain recovery watermark'); END;
CREATE TABLE app_recovery_captures (
 id TEXT PRIMARY KEY,source_generation TEXT NOT NULL,source_watermark INTEGER NOT NULL CHECK(source_watermark BETWEEN 0 AND 9007199254740991),
 schema_fingerprint TEXT NOT NULL,source_commit TEXT NOT NULL,created_ms INTEGER NOT NULL CHECK(created_ms>=0),updated_ms INTEGER NOT NULL CHECK(updated_ms>=created_ms),
 state TEXT NOT NULL CHECK(state IN ('reading','verifying','indexing','ready','held','superseded')),revision INTEGER NOT NULL CHECK(revision>=0),
 descriptor_json TEXT NOT NULL CHECK(json_valid(descriptor_json) AND length(CAST(descriptor_json AS BLOB))<=131072),
 checkpoint_json TEXT NOT NULL CHECK(json_valid(checkpoint_json) AND length(CAST(checkpoint_json AS BLOB))<=65536),
 root_json TEXT CHECK(root_json IS NULL OR json_valid(root_json) AND length(CAST(root_json AS BLOB))<=262144),root_digest TEXT,reason TEXT,
 CHECK((state='ready' AND root_json IS NOT NULL AND root_digest IS NOT NULL) OR (state<>'ready' AND root_json IS NULL AND root_digest IS NULL)),
 CHECK(state<>'held' OR reason IS NOT NULL)
) STRICT;
CREATE TRIGGER recovery_capture_ready_immutable BEFORE UPDATE ON app_recovery_captures WHEN OLD.state='ready' BEGIN SELECT RAISE(ABORT,'Completed recovery capture is immutable'); END;
CREATE TRIGGER recovery_capture_identity_immutable BEFORE UPDATE ON app_recovery_captures
 WHEN NEW.id IS NOT OLD.id OR NEW.source_generation IS NOT OLD.source_generation OR NEW.source_watermark IS NOT OLD.source_watermark OR NEW.schema_fingerprint IS NOT OLD.schema_fingerprint OR NEW.source_commit IS NOT OLD.source_commit OR NEW.created_ms IS NOT OLD.created_ms OR NEW.descriptor_json IS NOT OLD.descriptor_json OR NEW.revision<>OLD.revision+1
 BEGIN SELECT RAISE(ABORT,'Recovery capture identity or revision changed'); END;
CREATE TRIGGER recovery_capture_no_delete BEFORE DELETE ON app_recovery_captures BEGIN SELECT RAISE(ABORT,'Retain recovery capture'); END;
CREATE TABLE app_recovery_capture_pages (
 capture_id TEXT NOT NULL REFERENCES app_recovery_captures(id),scope TEXT NOT NULL,ordinal INTEGER NOT NULL CHECK(ordinal>=0),
 kind TEXT NOT NULL CHECK(kind IN ('rows','index','table','checkpoints')),
 identity_json TEXT NOT NULL CHECK(json_valid(identity_json) AND length(CAST(identity_json AS BLOB))<=1024),
 item_count INTEGER NOT NULL CHECK(item_count>=0),
 first_cursor_json TEXT CHECK(first_cursor_json IS NULL OR json_valid(first_cursor_json) AND length(CAST(first_cursor_json AS BLOB))<=4096),
 last_cursor_json TEXT CHECK(last_cursor_json IS NULL OR json_valid(last_cursor_json) AND length(CAST(last_cursor_json AS BLOB))<=4096),
 result_digest TEXT NOT NULL,PRIMARY KEY(capture_id,scope,ordinal)
) STRICT;
CREATE TABLE app_recovery_capture_objects (
 capture_id TEXT NOT NULL REFERENCES app_recovery_captures(id),object_key TEXT NOT NULL,
 identity_json TEXT NOT NULL CHECK(json_valid(identity_json) AND length(CAST(identity_json AS BLOB))<=1024),
 verified INTEGER NOT NULL CHECK(verified IN(0,1)),verification_digest TEXT,
 PRIMARY KEY(capture_id,object_key),CHECK((verified=0 AND verification_digest IS NULL) OR (verified=1 AND verification_digest IS NOT NULL))
) STRICT;
CREATE TRIGGER recovery_capture_object_monotonic BEFORE UPDATE ON app_recovery_capture_objects
 WHEN NEW.capture_id IS NOT OLD.capture_id OR NEW.object_key IS NOT OLD.object_key OR NEW.identity_json IS NOT OLD.identity_json OR OLD.verified<>0 OR NEW.verified<>1 OR OLD.verification_digest IS NOT NULL OR NEW.verification_digest IS NULL
 BEGIN SELECT RAISE(ABORT,'Recovery object identity or verification changed'); END;
CREATE TRIGGER recovery_capture_object_no_delete BEFORE DELETE ON app_recovery_capture_objects BEGIN SELECT RAISE(ABORT,'Retain recovery capture object'); END;
CREATE TABLE app_recovery_reconcile_checks (
 restore_id TEXT NOT NULL REFERENCES app_recovery_runs(id),phase TEXT NOT NULL,scope TEXT NOT NULL,ordinal INTEGER NOT NULL CHECK(ordinal>=0),
 target_watermark INTEGER NOT NULL CHECK(target_watermark BETWEEN 0 AND 9007199254740991),result_digest TEXT NOT NULL,item_count INTEGER NOT NULL CHECK(item_count>=0),
 PRIMARY KEY(restore_id,phase,scope,ordinal)
) STRICT;
CREATE TRIGGER app_recovery_capture_pages_no_update BEFORE UPDATE ON app_recovery_capture_pages BEGIN SELECT RAISE(ABORT,'Retain immutable recovery continuation evidence'); END;
CREATE TRIGGER app_recovery_capture_pages_no_delete BEFORE DELETE ON app_recovery_capture_pages BEGIN SELECT RAISE(ABORT,'Retain immutable recovery continuation evidence'); END;
CREATE TRIGGER app_recovery_reconcile_checks_no_update BEFORE UPDATE ON app_recovery_reconcile_checks BEGIN SELECT RAISE(ABORT,'Retain immutable recovery continuation evidence'); END;
CREATE TRIGGER app_recovery_reconcile_checks_no_delete BEFORE DELETE ON app_recovery_reconcile_checks BEGIN SELECT RAISE(ABORT,'Retain immutable recovery continuation evidence'); END;
